package com.wissenup.domain.timetable.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="class_timetable_details") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor
public class TimetableDetail { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="timetable_detail_id") private Long timetableDetailId; @Column(name="organization_id") private Long organizationId; @Column(name="class_timetable_id") private Long classTimetableId; @Column(name="day_of_week") private String dayOfWeek; @Column(name="period_id") private Long periodId; @Column(name="subject_id") private Long subjectId; @Column(name="staff_id") private Long staffId; @Column(name="room_number") private String roomNumber; private String status; @Column(name="created_at") private LocalDateTime createdAt; @Column(name="created_by") private Long createdBy; @Column(name="updated_at") private LocalDateTime updatedAt; @Column(name="updated_by") private Long updatedBy; @PrePersist void create(){if(status==null)status="ACTIVE";if(createdAt==null)createdAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} }
